const menu=document.querySelector('.menu');const nav=document.querySelector('.header nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.addEventListener('click',e=>{if(e.target.closest('a,button')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.querySelectorAll('[data-modal]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.modal==='contact'?'contact-dialog':'faq').showModal()));document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})});const finishes={Clear:'Clear — an open, light finish that keeps your essentials in view.',Frosted:'Frosted — a soft, understated finish for a considered bathroom.',Black:'Black — a bold, minimal finish that blends into your space.'};document.querySelectorAll('[data-finish]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-finish]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelector('.finish-caption').textContent=finishes[button.dataset.finish]}));document.getElementById('year').textContent=new Date().getFullYear();
